def solve(inputs: dict) -> float:
    matrix = inputs.get('matrix')
    exponent = inputs.get('exponent')
    modulus = inputs.get('modulus')

    # Matrix multiplication with modulo
    def matrix_mult(A, B, mod):
        n = len(A)
        m = len(B[0])
        k = len(B)
        C = [[0] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                for p in range(k):
                    C[i][j] = (C[i][j] + A[i][p] * B[p][j]) % mod
        return C

    # Matrix exponentiation using binary exponentiation
    def matrix_pow(M, exp, mod):
        n = len(M)
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]  # Copy M

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_pow(matrix, exponent, modulus)

    # Sum all entries
    total = 0
    for row in result_matrix:
        for entry in row:
            total += entry

    return float(total % modulus)

